export const ROGET_PACK: RawEntry[] = TSV.trim()
  .split('\n')
  .map((line) => {
    const [word, pos, meaning, theme] = line.split('\t')
    return { word, pos: pos || undefined, meaning, theme: theme || undefined }
  })
  .filter((e) => e.word && e.meaning)
